import { LineChart } from "march/charts"
import { Button } from "march/ui"

// iki arkadaşın adım yarışı: "Yürü" ikisine de rastgele adım ekler, çizgiler büyür; önde olan başlıkta
export function StepRace() {
  let $days = [{ gun: 1, ayse: 6200, mert: 5400 }]
  const walk = () => {
    const last = $days[$days.length - 1]
    if ($days.length >= 14) return
    $days = [...$days, { gun: last.gun + 1, ayse: last.ayse + 3000 + ($days.length * 977) % 5000, mert: last.mert + 2500 + ($days.length * 1361) % 6000 }]
  }
  const lead = () => { const l = $days[$days.length - 1]; return l.ayse >= l.mert ? "Ayşe önde 🏃‍♀️" : "Mert önde 🏃" }
  return <div sx={{ flex: "col", gap: 2 }}>
    <div sx={{ flex: ["row", "wrap", "center"], gap: 2 }}>
      <Button on:click={walk} disabled={() => $days.length >= 14}>Yürü</Button>
      <strong>{lead}</strong>
    </div>
    <LineChart data={() => $days} x="gun" y={["ayse", "mert"]} series={{ ayse: "Ayşe", mert: "Mert" }} xLabel="Gün" title="Adım yarışı" height={220} />
  </div>
}

import { LineChart, AreaChart } from "march/charts"
import { Card, Segmented } from "march/ui"

// bir e-ticaret panelinin gelir kartı: dönem seçilir, gelir ve gider çizgisi; altında etkin kullanıcıların alanı
const DAY = 864e5, START = Date.UTC(2026, 8, 1)
const wave = (i: number, base: number, amp: number, k: number) => Math.round(base + amp * Math.sin((i + k) / 3) + (amp / 2) * Math.cos((i * 7 + k) / 5) + i * base * 0.004)
const ALL = Array.from({ length: 90 }, (_, i) => ({ gun: START + i * DAY, gelir: wave(i, 42000, 9000, 1), gider: wave(i, 26000, 5000, 4), web: wave(i, 1800, 300, 2), uygulama: wave(i, 2600, 400, 5) }))

export function ShopRevenue() {
  let $range = "30"
  const rows = () => ALL.slice(-Number($range))
  return <Card title="Gelir ve gider" actions={[<Segmented size="sm" bind:value={$range} aria-label="Dönem" options={[{ value: "7", label: "7 gün" }, { value: "30", label: "30 gün" }, { value: "90", label: "90 gün" }]} />]}>
    <LineChart data={rows} x="gun" y={["gelir", "gider"]} series={{ gelir: "Gelir", gider: "Gider" }} format={["money", "TRY"]} xFormat="date" zoom title="Gelir ve gider" height={240} />
    <AreaChart data={rows} x="gun" y={["web", "uygulama"]} series={["Web", "Uygulama"]} stacked xFormat="date" title="Etkin kullanıcı" height={160} legend="right" />
  </Card>
}

import { LineChart, AreaChart } from "march/charts"
import { Button, Card } from "march/ui"

// LineChart ve AreaChart'ın bütün özellikleri: data (sinyal), x, y (liste ve getter), series, xType, xFormat, format,
// yMin, yMax, zero, grid, maxPoints, zoom, xLabel, tooltip, onSelect, stacked, title, description, empty, legend,
// class, colors, width, height
const rows = Array.from({ length: 24 }, (_, i) => ({ saat: i, ic: Math.round(18 + 6 * Math.sin((i - 9) / 4)), dis: Math.round(9 + 9 * Math.sin((i - 10) / 4)) }))

export function LineChartLab() {
  let $data = rows
  let $picked = "—"
  let $empty = false
  return <div sx={{ flex: "col", gap: 3 }}>
    <div sx={{ flex: ["row", "wrap", "center"], gap: 2 }}>
      <Button class="lab-shift" size="sm" on:click={() => { $data = $data.map((r) => ({ ...r, dis: r.dis + 2 })) }}>Dışarısı ısınsın</Button>
      <Button class="lab-empty" size="sm" variant="ghost" on:click={() => { $empty = !$empty }}>Veriyi boşalt / geri getir</Button>
      <span class="lab-picked">Seçilen: {() => $picked}</span>
    </div>
    <LineChart class="lab-line" data={() => ($empty ? [] : $data)} x="saat" xType="linear" xFormat={(h: number) => `${h}:00`} xLabel="Saat"
      y={["ic", (r: { dis: number }) => r.dis]} series={["İçeri", "Dışarı"]} format={(v: number) => `${v} °C`}
      yMin={0} yMax={30} grid="both" zoom maxPoints={500} legend="right" colors={["#f2801f", "#2f6fed"]}
      tooltip={(p: { x: unknown; y?: number | null; label?: unknown }) => `${p.label}: ${p.y} °C`} onSelect={(p: { x: unknown; y?: number | null; label?: unknown }) => { $picked = `${p.x}:00 · ${p.y} °C` }}
      title="Sıcaklık" description="İç ve dış sıcaklık, saat saat" empty="Ölçüm yok" height={240} />
    <Card m:theme="night">
      <AreaChart class="lab-area" data={() => $data} x="saat" y={["ic", "dis"]} series={{ ic: "İçeri", dis: "Dışarı" }} stacked zero
        grid={false} legend={false} width={320} height={140} title="Yığılmış alan" />
    </Card>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { LineChartLab } from "./LineChartLab.tsx"

// LineChartLab'in testleri: kaydedince Testler sekmesinde çalışır
test("iki seri iki çizgi; başlık ve açıklama SVG'de", () => {
  const s = renderTest(() => <LineChartLab />)
  const chart = s.get(".lab-line")!
  expect(chart.querySelectorAll(".m-chart-line").length).toBe(2)
  expect(chart.querySelector("svg title")!.textContent).toBe("Sıcaklık")
  expect(chart.querySelector("svg desc")!.textContent).toBe("İç ve dış sıcaklık, saat saat")
})

test("veri tablosu 24 saati taşır, veri değişince güncellenir", async () => {
  const s = renderTest(() => <LineChartLab />)
  const chart = s.get(".lab-line")!
  expect(chart.querySelectorAll("table tbody tr").length).toBe(24)
  const before = chart.querySelector("table tbody tr")!.textContent
  await s.click(".lab-shift")
  expect(chart.querySelector("table tbody tr")!.textContent).not.toBe(before)
})

test("veri boşalınca boş metni görünür", async () => {
  const s = renderTest(() => <LineChartLab />)
  await s.click(".lab-empty")
  expect(s.sees("Ölçüm yok")).toBe(true)
})

test("yığılmış alan grafiği iki alan çizer, açıklaması yok", () => {
  const s = renderTest(() => <LineChartLab />)
  const area = s.get(".lab-area")!
  expect(area.querySelectorAll(".m-chart-area").length).toBe(2)
  const legend = area.querySelector(".m-chart-legend")
  expect(legend == null || legend.hasAttribute("hidden")).toBe(true)
})
